   {
    "term": "Nitric oxide (NO)",
    "chapter_definition": "a gaseous signaling molecule that is generated by specific cells in the body and readily diffuses across cell membranes to regulate a wide range of physiologic and pathophysiologic processes."
   },
   {
    "term": "EDRF (endothelial-derived relaxing factor)",
    "chapter_definition": "a soluble factor released by endothelial cells in response to vasorelaxants that diffuses into vascular muscle and causes vasorelaxation; NO is the major bioactive component of EDRF."
   },
   {
    "term": "NOS isoforms",
    "chapter_definition": "neuronal NOS (nNOS or NOS-1), macrophage or inducible NOS (iNOS or NOS-2), and endothelial NOS (eNOS or NOS-3), each encoded by a separate gene and named for the initial cell type from which it was isolated."
   },
   {
    "term": "NOS reaction",
    "chapter_definition": "the NOS isoforms generate NO from the amino acid L-arginine in an O2- and NADPH-dependent reaction involving enzyme-bound cofactors heme, tetrahydrobiopterin, and FAD."
   },
   {
    "term": "iNOS regulation",
    "chapter_definition": "iNOS is not regulated by calcium, but instead produces NO in proportion to the expression level of iNOS, which is induced by inflammatory mediators."
   },
   {
    "term": "Soluble guanylyl cyclase (sGC)",
    "chapter_definition": "a heme-containing enzyme that generates cGMP from GTP; NO binds and activates sGC activity several hundredfold."
   },
   {
    "term": "NO donors",
    "chapter_definition": "prodrugs that require biotransformation in order to release NO; they do not spontaneously release NO."
   },
   {
    "term": "Peroxynitrite (ONOO-)",
    "chapter_definition": "formed when large amounts of both NO and superoxide are produced; a highly reactive and short-lived oxidant that leads to nitration of tyrosine and DNA."
   }
